# exact-cover tilings of nonzero cells by 2x2 full/L pieces
G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
ones={(r,c) for r,row in enumerate(G) for c,v in enumerate(row) if v}
placements=[]
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for miss in [None,(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   cells=box if miss is None else box-{miss}
   if cells<=ones:
    placements.append((r,c,miss,cells))
sol=[]
def search(rem, chosen):
 if not rem:
  sol.append(chosen); return
 x=min(rem)
 for p in placements:
  if x in p[3] and p[3]<=rem:
   search(rem-p[3],chosen+[p])
search(ones,[])
len(sol), [[(p[0],p[1],p[2],len(p[3])) for p in s] for s in sol[:10]]
